<?php

declare(strict_types=1);

namespace App\Models;

use App\Models\Concerns\HasUuidPrimaryKey;
use Illuminate\Database\Eloquent\Model;
use Illuminate\Database\Eloquent\Relations\BelongsTo;

/**
 * A persisted recommendation (brief §48, §52–53): structured as immediate
 * mitigation, short-term fix, permanent fix or verification; classified as a
 * safe check, a potential fix or a high-risk change; generated by a rule or
 * by AI (with prompt version and run); reviewed by a person. Never
 * overwritten — a new recommendation is a new row.
 */
class IntelligenceRecommendation extends Model
{
    use HasUuidPrimaryKey;

    public const CATEGORIES = ['immediate', 'short_term', 'permanent', 'verification', 'management'];

    public const RISKS = ['safe_check', 'potential_fix', 'high_risk'];

    public const REVIEWS = ['pending', 'useful', 'not_useful', 'accepted', 'rejected', 'incorrect_diagnosis'];

    public const SOURCES = ['incident', 'insight', 'forecast', 'data_quality'];

    protected $fillable = [
        'source_type', 'source_id', 'incident_id', 'area', 'category', 'risk', 'title', 'body', 'evidence', 'confidence',
        'generated_by', 'prompt_version', 'ai_run_id', 'generated_at', 'review_status', 'reviewed_by', 'reviewed_at', 'review_note', 'linked_action_reference',
    ];

    protected function casts(): array
    {
        return [
            'evidence' => 'array',
            'generated_at' => 'datetime',
            'reviewed_at' => 'datetime',
        ];
    }

    public function incident(): BelongsTo
    {
        return $this->belongsTo(IntelligenceIncident::class, 'incident_id');
    }

    public function reviewer(): BelongsTo
    {
        return $this->belongsTo(User::class, 'reviewed_by');
    }
}
